/**
 * One system reading per operation. Audit timestamps are always generated by
 * this module; model-supplied audit times are dropped and reported as a
 * violation by the write layer.
 */
export function createClock(options = {}) {
  let lastWall = null;
  let lastAt = null;
  const source = typeof options.now === 'function' ? options.now : () => new Date();

  function read() {
    const date = source();
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
      throw new TypeError('invalid_clock_reading');
    }
    return date;
  }

  return {
    /** ISO-8601 UTC instant, used for every recorded/observed/*_at column. */
    at() {
      const date = read();
      const at = date.toISOString();
      if (lastWall !== null && date.getTime() < lastWall) {
        const anomaly = { previous: lastAt, current: at, kind: 'clock_backwards' };
        lastWall = date.getTime();
        lastAt = at;
        return { at, anomaly };
      }
      lastWall = date.getTime();
      lastAt = at;
      return { at, anomaly: null };
    },
    /** Local calendar date used by origin labels such as master@YYYY-MM-DD. */
    localDate(date = read()) {
      const y = date.getFullYear();
      const m = String(date.getMonth() + 1).padStart(2, '0');
      const d = String(date.getDate()).padStart(2, '0');
      return `${y}-${m}-${d}`;
    },
    /** True when the wall clock moved backwards since the previous reading. */
    isBackwards(previousAt, currentAt) {
      if (previousAt === null || currentAt === null) return false;
      return Date.parse(currentAt) < Date.parse(previousAt);
    },
    now() {
      return read();
    },
  };
}

export const systemClock = createClock();
